ALTER TABLE "match_participants" ADD CONSTRAINT "match_participants_identity_ck" CHECK (("match_participants"."kind" = 'PLAYER' and "match_participants"."player_id" is not null and "match_participants"."guest_display_name" is null and "match_participants"."guest_created_by_player_id" is null) or ("match_participants"."kind" = 'GUEST' and "match_participants"."player_id" is null and "match_participants"."guest_display_name" is not null and btrim("match_participants"."guest_display_name") <> '' and "match_participants"."guest_created_by_player_id" is not null));